import React from 'react';
import { Navbar, Nav, Container, Dropdown, Badge } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { getUser, logout } from '../../utils/auth';

const Header = () => {
  const navigate = useNavigate();
  const user = getUser();

  const handleLogout = () => {
    if (window.confirm('Apakah Anda yakin ingin logout?')) {
      logout();
      navigate('/login');
    }
  };

  const getRoleColor = (role) => {
    switch (role) {
      case 'admin': return 'danger';
      case 'logistik': return 'warning';
      case 'user': return 'success';
      default: return 'secondary';
    }
  };

  const getRoleIcon = (role) => {
    switch (role) {
      case 'admin': return 'fas fa-crown';
      case 'logistik': return 'fas fa-tools';
      case 'user': return 'fas fa-user';
      default: return 'fas fa-user-circle';
    }
  };

  return (
    <Navbar expand="lg" className="shadow-sm sticky-top">
      <Container fluid>
        <Navbar.Brand className="d-flex align-items-center">
          <div className="d-flex align-items-center">
            <div 
              className="bg-gradient-primary rounded-circle d-flex align-items-center justify-content-center me-3"
              style={{ width: '40px', height: '40px' }}
            >
              <i className="fas fa-building text-white"></i>
            </div>
            <div>
              <div className="fw-bold text-gradient fs-4">BRIRoom</div>
              <small className="text-muted">Sistem Booking Ruangan</small>
            </div>
          </div>
        </Navbar.Brand>
        
        <Navbar.Toggle aria-controls="navbar-nav" />
        <Navbar.Collapse id="navbar-nav" className="justify-content-end">
          <Nav className="align-items-center">
            {/* Notification Bell */}
            <Nav.Item className="me-3">
              <div className="position-relative">
                <i className="fas fa-bell fs-5 text-muted cursor-pointer"></i>
                <Badge 
                  bg="danger" 
                  pill 
                  className="position-absolute top-0 start-100 translate-middle"
                  style={{ fontSize: '0.6rem' }}
                >
                  3
                </Badge>
              </div>
            </Nav.Item>

            {/* User Dropdown */}
            <Dropdown align="end">
              <Dropdown.Toggle 
                variant="outline-primary" 
                id="user-dropdown"
                className="d-flex align-items-center border-2"
              >
                <div className="d-flex align-items-center">
                  <div 
                    className="bg-gradient-primary rounded-circle d-flex align-items-center justify-content-center me-2"
                    style={{ width: '32px', height: '32px' }}
                  >
                    <i className={`${getRoleIcon(user?.role)} text-white`} style={{ fontSize: '0.9rem' }}></i>
                  </div>
                  <div className="text-start d-none d-md-block">
                    <div className="fw-bold" style={{ fontSize: '0.9rem' }}>
                      {user?.name || user?.email}
                    </div>
                    <small className="text-muted">
                      {user?.role?.charAt(0).toUpperCase() + user?.role?.slice(1)}
                    </small>
                  </div>
                </div>
              </Dropdown.Toggle>
              
              <Dropdown.Menu className="shadow-strong">
                <Dropdown.Header>
                  <div className="d-flex align-items-center">
                    <i className={`${getRoleIcon(user?.role)} me-2 text-primary`}></i>
                    <div>
                      <div className="fw-bold text-dark">{user?.name || user?.email}</div>
                      <small className="text-muted d-flex align-items-center">
                        <Badge bg={getRoleColor(user?.role)} className="me-1">
                          {user?.role?.toUpperCase()}
                        </Badge>
                        {user?.role === 'admin' && 'Administrator'}
                        {user?.role === 'logistik' && 'Staff Logistik'}
                        {user?.role === 'user' && 'User'}
                      </small>
                    </div>
                  </div>
                </Dropdown.Header>
                
                <Dropdown.Divider />
                
                <Dropdown.Item className="d-flex align-items-center">
                  <i className="fas fa-user-edit me-2 text-info"></i>
                  Edit Profile
                </Dropdown.Item>
                
                <Dropdown.Item className="d-flex align-items-center">
                  <i className="fas fa-cog me-2 text-secondary"></i>
                  Pengaturan
                </Dropdown.Item>
                
                <Dropdown.Item className="d-flex align-items-center">
                  <i className="fas fa-question-circle me-2 text-primary"></i>
                  Bantuan
                </Dropdown.Item>
                
                <Dropdown.Divider />
                
                <Dropdown.Item 
                  onClick={handleLogout}
                  className="d-flex align-items-center text-danger"
                >
                  <i className="fas fa-sign-out-alt me-2"></i>
                  Logout
                </Dropdown.Item>
              </Dropdown.Menu>
            </Dropdown>
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
};

export default Header;
